"""
    Inputs:
        two lists of primers

    get matching primers from a list (get primer pair from same amplicon)

    Returns:
        matched primer pair (same amplicon) if any

    """
def get_matched_primer_pair(le: Any, ri: Any) -> object {
    for l in le {
        for r in ri {
            if (l[2] == r[2]) {
                return (l, r);
            }
        }
    }
    return (None, None);
}

